      "content": "import React from 'react';
import { render, screen } from '@testing-library/react';
import { FeatureComparisonTable } from '../FeatureComparisonTable';

describe('FeatureComparisonTable', () => {
  const plans = [
    { id: 'starter', name: 'Starter', price: '$9/mo', features: ['users', 'storage', 'support'], ctaLabel: 'Get Started', recommended: false },
    { id: 'pro', name: 'Pro', price: '$29/mo', features: ['users', 'storage', 'support', 'analytics', 'custom-domain'], ctaLabel: 'Choose Pro', recommended: true },
    { id: 'business', name: 'Business', price: '$99/mo', features: ['users', 'storage', 'support', 'analytics', 'custom-domain', 'priority-support'], ctaLabel: 'Contact Sales', recommended: false },
  ];
  const features = [
    { key: 'users', label: 'Up to 5 users' },
    { key: 'storage', label: '10GB storage' },
    { key: 'support', label: 'Email support' },
    { key: 'analytics', label: 'Advanced analytics' },
    { key: 'custom-domain', label: 'Custom domain' },
    { key: 'priority-support', label: 'Priority support' },
  ];

  it('renders table headers for each plan', () => {
    render(<FeatureComparisonTable plans={plans} features={features} />);
    plans.forEach((plan) => {
      expect(screen.getByText(plan.name)).toBeInTheDocument();
    });
  });

  it('renders feature labels', () => {
    render(<FeatureComparisonTable plans={plans} features={features} />);
    features.forEach((feature) => {
      expect(screen.getByText(feature.label)).toBeInTheDocument();
    });
  });

  it('shows check icon for included features', () => {
    render(<FeatureComparisonTable plans={plans} features={features} />);
    // Should find at least one included icon
    expect(screen.getAllByLabelText('Included').length).toBeGreaterThan(0);
  });

  it('shows cross icon for not included features', () => {
    render(<FeatureComparisonTable plans={plans} features={features} />);
    // Should find at least one not included icon
    expect(screen.getAllByLabelText('Not included').length).toBeGreaterThan(0);
  });

  it('is accessible via table role', () => {
    render(<FeatureComparisonTable plans={plans} features={features} />);
    expect(screen.getByRole('table')).toBeInTheDocument();
  });
});
